import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds 124.5 to 124 (banker\'s rounding)', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents rounds 125.5 to 126 (banker\'s rounding)', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds 2.4 to 2', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents rounds -0.5 to 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros formats 123456 as €1,234.56', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros formats -5 as -€0.05', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros parses "12" as 1200 cents', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros parses "12.5" as 1250 cents', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros parses "1,234.56" as 123456 cents', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('RATES has EUR, USD, GBP', () => {
  assert.ok('EUR' in RATES);
  assert.ok('USD' in RATES);
  assert.ok('GBP' in RATES);
});

test('RATES EUR is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES USD is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES GBP is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert EUR to USD', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 108);
});

test('convert EUR to GBP', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 84);
});

test('convert 0 EUR to USD', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert large amount EUR to USD', () => {
  const result = convert(850000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 922250);
});

test('convert rejects unknown currency', () => {
  const result = convert(100, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert rejects lowercase currency', () => {
  const result = convert(100, 'usd');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('formatMoney EUR formats as plain amount', () => {
  assert.equal(formatMoney(123456, 'EUR'), '1234.56');
});

test('formatMoney USD formats with dollar sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1234.56');
});

test('formatMoney GBP formats with pound sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1234.56');
});

test('formatMoney EUR negative', () => {
  assert.equal(formatMoney(-123456, 'EUR'), '-1234.56');
});

test('formatMoney USD negative', () => {
  assert.equal(formatMoney(-123456, 'USD'), '-$1234.56');
});

test('formatMoney GBP negative', () => {
  assert.equal(formatMoney(-123456, 'GBP'), '-£1234.56');
});

test('formatMoney zero amount', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney small amount', () => {
  assert.equal(formatMoney(5, 'EUR'), '0.05');
});

test('formatMoney has 2 decimal places', () => {
  assert.equal(formatMoney(1234, 'USD'), '$12.34');
});

test('formatMoney uses dot decimal separator', () => {
  assert.ok(formatMoney(123456, 'EUR').includes('.'));
});

test('formatMoney does not use thousands separator', () => {
  assert.ok(!formatMoney(123456, 'EUR').includes(','));
});

test('convert rounds correctly for USD', () => {
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
  assert.equal(Number.isInteger(result.value), true);
});

test('convert rounds correctly for GBP', () => {
  const result = convert(123, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
  assert.equal(Number.isInteger(result.value), true);
});

test('convert and formatMoney roundtrip', () => {
  const eurCents = 100000;
  const usdResult = convert(eurCents, 'USD');
  assert.equal(usdResult.ok, true);
  const formatted = formatMoney(usdResult.value, 'USD');
  assert.ok(formatted.startsWith('$'));
});

test('convert multiple times compounds correctly', () => {
  const eurCents = 100;
  const usdResult = convert(eurCents, 'USD');
  const gbpResult = convert(eurCents, 'GBP');
  assert.ok(usdResult.value > eurCents);
  assert.ok(gbpResult.value < eurCents);
});

test('formatMoney EUR for large amount', () => {
  const formatted = formatMoney(1000000, 'EUR');
  assert.equal(formatted, '10000.00');
});

test('formatMoney USD for large amount', () => {
  const formatted = formatMoney(1000000, 'USD');
  assert.equal(formatted, '$10000.00');
});

test('convert negative amount EUR to USD', () => {
  const result = convert(-100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -108);
});

test('formatMoney unknown currency defaults to plain format', () => {
  const formatted = formatMoney(123456, 'XXX');
  assert.equal(formatted, '1234.56');
});

